const defaultOptions: Promotion618Options = { rate: 0.18 };

export function apply618Discount(total: Money): Money {
  if (total < 0) return 0;
  return total - total * defaultOptions.rate;
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { apply618Discount } from "../src/promotions618.ts";

test("618 优惠减免原价 18%", () => {
  assert.equal(apply618Discount(100), 82);
});
test("618 优惠对负数返回 0", () => {
  assert.equal(apply618Discount(-10), 0);
});
test("618 优惠对零返回 0", () => {
  assert.equal(apply618Discount(0), 0);
});

